-- Automatically record every case update in the existing administrator audit log.
create or replace function public.audit_spike_abuse_case_change() returns trigger language plpgsql security definer set search_path=pg_catalog,public as $function$ declare v_actor uuid:=auth.uid(); v_role text; begin if v_actor is not null then select p.role into v_role from public.profiles p where p.id=v_actor; end if; insert into public.admin_audit(actor_id,action,target_user_id,role,details) values(v_actor,'abuse_case_updated',new.subject_user_id,coalesce(v_role,'system'),jsonb_build_object('case_id',new.id,'source',new.source,'source_id',new.source_id,'reporter_id',new.reporter_id,'before',jsonb_build_object('status',old.status,'severity',old.severity,'assigned_to',old.assigned_to,'resolution',old.resolution),'after',jsonb_build_object('status',new.status,'severity',new.severity,'assigned_to',new.assigned_to,'resolution',new.resolution))); return new; end; $function$;
revoke all on function public.audit_spike_abuse_case_change() from public,anon,authenticated; drop trigger if exists spike_abuse_case_admin_audit on public.spike_abuse_cases; create trigger spike_abuse_case_admin_audit after update on public.spike_abuse_cases for each row when(old.status is distinct from new.status or old.severity is distinct from new.severity or old.assigned_to is distinct from new.assigned_to or old.resolution is distinct from new.resolution) execute function public.audit_spike_abuse_case_change();
